export function ownerF228BaseMaterials(components:BuildingComponent[],paint:Float32Array,frames:Float32Array){let offset=0,objects=0,vertices=0;for(const c of components){const match=c.city==='leipzig'&&ownerF228Identity(c)&&!!c.displayEstimates?.F228Exterior;if(match)objects++;for(const b of c.batches){const count=b.positions.length/3;if(match){frames.set((b as Batch).frames,offset*5);paint.set((b as Batch).paint,4*offset);vertices+=count;}offset+=count;}}return{objects,vertices,actualVisualAccepted:false};}
